export function EraCard(a,r=!1){return`<div class="era-card ${r?"selected":""}" data-id="${a.id}">\n    <div class="era-card-image">\n      <img src="${a.image}" alt="${a.name}" loading="lazy" />\n      <div class="era-card-overlay" style="border-left-color: ${a.color}">\n        <span class="era-period">${a.period}</span>\n      </div>\n    </div>\n    <div class="era-card-body">\n      <h3 class="era-card-name">${a.name}</h3>\n      <p class="era-card-summary">${a.summary}</p>\n      <button class="era-card-btn" data-id="${a.id}">\n        Learn more <span class="arrow">→</span>\n      </button>\n    </div>\n  </div>`}export function EraDetail(a){const r=a.keyFacts.map(a=>`<li>${a}</li>`).join("");return`<div class="era-detail" style="border-top-color: ${a.color}">\n    <div class="era-detail-header">\n      <h2>${a.name}</h2>\n      <span class="era-detail-period">${a.period}</span>\n    </div>\n    <p class="era-detail-summary">${a.summary}</p>\n    <h4>Key Facts</h4>\n    <ul class="era-detail-facts">${r}</ul>\n  </div>`}